#include <iostream>
#include <vector>
#include <algorithm>

// Bubble sort function: sorts a vector in ascending order
void bubbleSort(std::vector<int>& nums)
{
    int n = nums.size();
    // Outer loop controls how many rounds of comparisons are needed
    for (int i = 0; i < n - 1; i++)
    {
        // Inner loop performs comparison and swapping of adjacent elements in each round
        // After each round, the largest element "bubbles up" to the end of the array, so one less comparison can be made
        for (int j = 0; j < n - i - 1; j++)
        {
            if (nums[j] > nums[j + 1])
            {
                std::swap(nums[j], nums[j + 1]);
            }
        }
    }
}

// Helper function to print vector elements
void printVector(const std::vector<int>& nums)
{
    for (int num : nums)
    {
        std::cout << num << " ";
    }
    std::cout << std::endl;
}

