// Thread function: processes a segment of data (core logic unchanged, optimized parameter types)
void processSegment(std::vector<int>& data, size_t start, size_t end, int multiplier) 
{
    // Use size_t: avoids int overflow (safer when handling very large datasets)
    for (size_t i = start; i < end; ++i)
    {
        data[i] *= multiplier;
    }
}

// Creates threads and assigns tasks (optimized boundary handling and safety checks)
void processLargeData(std::vector<int>& data, int threadNum, int multiplier) {
    // 1. Handle empty dataset: return directly to avoid subsequent invalid calculations
    if (data.empty()) 
    {
        return;
    }

    // 2. Adjust thread count: ensure it's within a reasonable range (1 ~ data size)
    size_t dataSize = data.size();
    size_t validThreadNum = static_cast<size_t>(threadNum);
    validThreadNum = std::max(static_cast<size_t>(1), std::min(validThreadNum, dataSize));
    size_t segmentSize = dataSize / validThreadNum;
    size_t remaining = dataSize % validThreadNum; // Remaining data amount (assigned to the last thread)

    // 3. Create threads: add exception catching to avoid crashes caused by thread creation failure
    std::vector<std::thread> threads;
    try 
    {
        size_t currentStart = 0;
        for (size_t i = 0; i < validThreadNum; ++i) 
        {   // Use size_t: matches the data size type
            size_t currentEnd = currentStart + segmentSize;
            // The last thread handles the remaining data (adds 'remaining' when i == validThreadNum - 1)
            if (i == validThreadNum - 1)
            {
                currentEnd += remaining;
            }
            threads.emplace_back(processSegment, std::ref(data), currentStart, currentEnd, multiplier);
            currentStart = currentEnd;
            // emplace_back may throw exceptions (e.g., insufficient system resources), catch with try-catch
        }
    }
    catch (const std::system_error& e) 
    {
        // Thread creation failed: output error message and wait for already created threads to finish
        std::cerr << "Thread creation failed: " << e.what() << std::endl;
        for (auto& t : threads)
        {
            if (t.joinable())
            {
                t.join();
            }
        }
        return;
    }

    // 4. Wait for all created threads to finish (ensures no thread leaks, regardless of creation failures)
    for (auto& t : threads)
    {
        if (t.joinable())
        {
            t.join();
        }
    }
}

// Generate test case data (logic unchanged, optimized parameter description)
std::vector<int> generateTestData(size_t size, int start = 1) 
{   
    // Use size_t: clarifies the unsigned nature of "quantity"
    std::vector<int> data(size);
    // Generate consecutive integers: [start, start+1, ..., start+size-1]
    std::iota(data.begin(), data.end(), start);
    return data;
}

// Calculate expected result (logic unchanged)
std::vector<int> getExpectedResult(const std::vector<int>& original, int multiplier) 
{
    std::vector<int> expected = original;
    for (auto& val : expected)
    {
        val *= multiplier;
    }
    return expected;
}

// Check if the result is correct (logic unchanged, optimized parameter types)
bool checkResult(const std::vector<int>& result, const std::vector<int>& expected) 
{
    // Use std::equal for element-by-element comparison to ensure results match
    return result.size() == expected.size() && std::equal(result.begin(), result.end(), expected.begin());
}

// Print vector contents (optimized output format, added empty vector check)
void printVector(const std::vector<int>& v, size_t maxElements = 10) 
{
    if (v.empty()) 
    {  // Handle empty vector separately to avoid abnormal formats like "[, ...]"
        std::cout << "[]";
        return;
    }

    std::cout << "[";
    size_t count = 0;
    for (const auto& val : v) {
        if (count >= maxElements) {
            std::cout << ", ...";
            break;
        }
        if (count > 0) {
            std::cout << ", ";
        }
        std::cout << val;
        ++count;
    }
    std::cout << "]";
}

