#include <iostream>
#include <vector>
#include <algorithm>
#include <climits> // Contains definitions for INT_MAX and INT_MIN
using namespace std;

// Helper function to print vector contents
void printVector(const vector<int>& vec) {
    cout << "[";
    for (size_t i = 0; i < vec.size(); ++i) {
        cout << vec[i];
        if (i != vec.size() - 1) {
            cout << ", ";
        }
    }
    cout << "]";
}

// Remove duplicate elements from a vector (maintains sorted order after deduplication)
vector<int> removeDuplicates(vector<int>& data) {
    // Handle empty vector case
    if (data.empty()) {
        return {};
    }

    // Sort to make identical elements adjacent
    sort(data.begin(), data.end());

    // Deduplication logic: keep the first occurrence and elements different from the previous one
    vector<int> result;
    result.push_back(data[0]);
    for (size_t i = 1; i < data.size(); ++i) {
        if (data[i] != data[i - 1]) {
            result.push_back(data[i]);
        }
    }

    return result;
}

