#define _CRT_SECURE_NO_WARNINGS 1
#include <iostream>
#include <cstring>
using namespace std;

void reverseString(char* str)
{
    // Defensive check: verify if the input pointer is NULL
    if (str == nullptr) {
        return;
    }

    // Calculate the length of the string
    int length = strlen(str);

    // Handle cases of empty string or single-character string (no need to reverse)
    if (length <= 1) {
        return;
    }

    // Initialize two pointers: left pointer points to the beginning of the string, right pointer points to the last valid character
    char* left = str;
    char* right = str + length - 1;

    // Reverse the string using the two-pointer swap method
    while (left < right) {
        // Swap the characters pointed to by the two pointers
        char temp = *left;
        *left = *right;
        *right = temp;

        // Move the pointers
        left++;
        right--;
    }
}


int main() {
    struct TestCase {
        char original[50];
        const char* expected;
    };

    TestCase testCases[] = {
        {" ", " "}
    };

    size_t caseCount = sizeof(testCases) / sizeof(testCases[0]);

    for (size_t i = 0; i < caseCount; i++) {
        cout << "=== Test Case " << (i + 1) << " ===" << endl;
        char originalCopy[50];
        strcpy(originalCopy, testCases[i].original);

        reverseString(testCases[i].original);

        bool isMatch = (strcmp(testCases[i].original, testCases[i].expected) == 0);

        cout << 'Original String:  '<< originalCopy << '  ' << endl;
        cout << 'Actual Reversed Result: " '<< testCases[i].original << ' " ' << endl;
        cout << 'Expected Reversed Result: " ' << testCases[i].expected << ' " ' << endl;

        if (i == 15) {
            cout << "Note: Chinese characters are multi-byte characters, single-byte reversal will cause garbled text. This case is for demonstration only." << endl;
        }

        cout << "Result Match: " << (isMatch ? "true" : "false") << " " << endl;
    }

    return 0;
}

