};

// Function 1: Dynamically create point cloud arrays (allocate memory for x/y/z coordinates)
// Function 2: Free point cloud memory (avoid memory leaks)
// Function 3: Fill simulated point cloud data (generate x/y/z within specified ranges)
// Function 4: Calculate the average distance from the point cloud to the origin
// Function 5: Find the maximum distance in the point cloud (the point farthest from the origin)
// Function 6: Find the minimum distance in the point cloud (the point closest to the origin)
// Function 7: Count the number of points in the point cloud with z-axis height ≥ threshold (identify aerial obstacles)
// Function 8: Count the number of points in the point cloud within a specified x-axis range (identify obstacles in a specific area)
// Function 9: Calculate the average z-axis height of the point cloud
// Function 10: Check if floating-point numbers are equal (with tolerance)
// Function 11: Case result output and verification (general function)

void printCaseResult(int caseIdx, const string& desc, int actual, int expected, const string& unit) {
    cout << "【Case" << caseIdx << "】" << desc << endl;
    cout << "  Actual result: " << actual << unit << endl;
    cout << "  Expected result: " << expected << unit << endl;
    cout << "  Verification result: " << (actual == expected ? "true" : "false") << " " << endl;
}

void printCaseResult(int caseIdx, const string& desc, bool actual, bool expected) {
    cout << "【Case" << caseIdx << "】" << desc << endl;
    cout << "  Actual result: " << (actual ? "Yes" : "No") << endl;
    cout << "  Expected result: " << (expected ? "Yes" : "No") << endl;
    cout << "  Verification result: " << (actual == expected ? "true" : "false") << " " << endl;
}

