#include <iostream>
using namespace std;

// Soil monitoring data structure: stores the monitoring point ID and a pointer to 3-dimensional features (temperature, humidity, pH value)
// struct SoilData is used to store core information for a single monitoring point: siteID: string pointer, stores the unique ID of the monitoring point (e.g., site001); features: float pointer, points to an array of 3-dimensional features (fixed order: temperature → humidity → pH value)
// Planting suitability judgment function isSuitable: Core logic: only judges whether the pH value is within the range of 6.0 - 7.5 (the suitable interval defined by the paper); Pointer operation: obtains the pH value via * (soil.features + 2) (equivalent to soil.features[2], pointer offset by 2 positions to the third element)

int main() {
    // -------------------------- 20 monitoring point feature data --------------------------
    // Format: float featX[] = {temperature, humidity, pH value}; Expected result: suitable(true)/unsuitable(false)
    float feat1[] = { 25.3, 65.2, 6.8 };  // site001: pH=6.8 → expected true

    // -------------------------- Construct dataset of 20 monitoring points --------------------------
    SoilData soilDataset[] = {
        {"site001", feat1}
    };
    // Calculate dataset size (total bytes / bytes of a single SoilData)
    int dataSize = sizeof(soilDataset) / sizeof(soilDataset[0]);

    // -------------------------- Single case judgment and verification --------------------------
    cout << "=== 20 monitoring points planting suitability judgment results === ";
    for (int i = 0; i < dataSize; i++) {
        SoilData currentSoil = soilDataset[i];
        // 1. Output basic information of the current monitoring point
        cout << "【" << currentSoil.siteID << "】 ";
        cout << "  Temperature: " << currentSoil.features[0] << "℃ | Humidity: " << currentSoil.features[1] << "% | pH value: " << currentSoil.features[2] << " ";

        // 2. Call the judgment function to get the actual result
        bool actualResult = isSuitable(currentSoil);
        cout << "  Actual judgment: " << (actualResult ? "Suitable for planting" : "Not suitable for planting") << " ";

        // 3. Define the expected result for each case (corresponding to the expectation of featX)
        bool expectedResult;
        switch (i) {
        case 0: case 2: case 4: case 6: case 8: case 10: case 12: case 14: case 17: case 19:
            expectedResult = true;  // 10 suitable cases
            break;
        default:
            expectedResult = false; // 10 unsuitable cases
            break;
        }

        // 4. Verify whether the actual result matches the expected result
        bool isCheckPass = (actualResult == expectedResult);
        cout << "  Result verification: " << (isCheckPass ? "true" : "false") << "  ";
    }

    // -------------------------- Overall statistical verification --------------------------
    int suitableCount = 0;
    SoilData* soilPtr = soilDataset; // Pointer to traverse the dataset
    for (int i = 0; i < dataSize; i++) {
        if (isSuitable(*soilPtr)) suitableCount++;
        soilPtr++;
    }
    cout << "=== Overall statistical verification ===" << endl;
    cout << "Total number of monitoring points suitable for planting: " << suitableCount << " (Expected: 10) ";
    cout << "Overall verification result: " << (suitableCount == 10 ? "true" : "false") << endl;

    return 0;
}

