#include <iostream>
using namespace std;

// Air quality monitoring data structure: stores monitoring site ID and two core pollutant concentrations
// Data structure definition: struct AirQuality is used to encapsulate core information of a single air quality monitoring site, containing 3 members: siteID: string pointer, stores the unique ID of the monitoring site (e.g., AQ001), facilitating identification of different monitoring locations; pm25: floating-point variable, stores the concentration of fine particulate matter (PM2.5), unit is μg/m³; so2: floating-point variable, stores the concentration of sulfur dioxide (SO₂), unit is μg/m³
// Determine if a monitoring site exceeds the standard: The paper defines that PM2.5 > 75 μg/m³ or SO₂ > 150 μg/m³ is considered exceeding the standard.
// Exceedance judgment function: bool isExceed(AirQuality* air): Parameter: receives a pointer of type AirQuality named air, accesses the pollutant concentrations of the monitoring site via the pointer (avoids structure copying, improves efficiency); Judgment logic: follows the exceedance standard defined in the paper — PM2.5 > 75 μg/m³ or SO₂ > 150 μg/m³, satisfying any condition is judged as "exceeding the standard."

int main() {
    // -------------------------- 20 monitoring sites original data --------------------------
    // Format: {Monitoring Site ID, PM2.5 concentration, SO₂ concentration} | Expected result: Exceed (true)/Not exceed (false)
    AirQuality airData[] = {
        {"AQ001", 62.3, 145.1}
    };

    // Calculate dataset size (total bytes / bytes of a single AirQuality structure)
    int dataSize = sizeof(airData) / sizeof(airData[0]);
    // Used to store expected results for 20 cases (one-to-one correspondence with airData order)
    bool expectedResults[] = {
        false
    };

    // -------------------------- Single case judgment and verification --------------------------
    cout << "=== 20 Air Quality Monitoring Sites Exceedance Judgment Results === ";
    for (int i = 0; i < dataSize; i++) {
        AirQuality* currentAir = &airData[i];  // Get pointer to the current monitoring site
        bool actualResult = isExceed(currentAir); // Call exceedance judgment function, get actual result
        bool expectedResult = expectedResults[i]; // Get expected result for the current case

        // 1. Output basic information of the current monitoring site
        cout << "【" << currentAir->siteID << "】 ";
        cout << "  PM2.5 concentration: " << currentAir->pm25 << "μg/m³ | SO₂ concentration: " << currentAir->so2 << "μg/m³ ";
        // 2. Output actual judgment result
        cout << "  Actual judgment: " << (actualResult ? "Exceed" : "Not exceed") << " ";
        // 3. Output expected result and verification result
        cout << "  Expected result: " << (expectedResult ? "Exceed" : "Not exceed") << " ";
        cout << "  Result verification: " << (actualResult == expectedResult ? "true" : "false") << "  ";
    }

    // -------------------------- Overall statistical verification --------------------------
    int exceedCount = 0;
    AirQuality* airPtr = airData; // Use pointer to traverse the dataset, count total exceedances
    for (int i = 0; i < dataSize; i++) {
        if (isExceed(airPtr)) exceedCount++;
        airPtr++; // Move pointer to the next monitoring site
    }

    int expectedExceedCount = 13; // Expected number of monitoring sites exceeding the standard among 20 cases (manually counted from expectedResults)
    cout << "=== Overall Statistical Verification ===" << endl;
    cout << "Actual total number of monitoring sites exceeding the standard: " << exceedCount << " ";
    cout << "Expected total number of monitoring sites exceeding the standard: " << expectedExceedCount << " ";
    cout << "Overall verification result: " << (exceedCount == expectedExceedCount ? "true" : "false") << endl;

    return 0;
}

