using namespace std;

// Added core function declaration (original code called it without declaration, to avoid compilation errors)
void calibratePH(float* phArr, int len, float offset);

// Core functionality: pH calibration function calibratePH function: Adds a specified offset to all elements in the passed pH data array, used to correct systematic errors of the sensor (e.g., fixed deviation after long-term sensor use)
// Pointer operation core: 1. Define pointer ptr initially pointing to the first element of the array phArr (array name is essentially a pointer to the first element); 2. In the loop, use *ptr += offset to dereference the pointer and directly modify the pH value it currently points to (equivalent to phArr[i] += offset); 3. After each loop, ptr++ moves the pointer backward by 1 position, pointing to the next element of the array, until all data is traversed.
// Test case structure PHTestCase function: Encapsulates each test case's "original pH data, calibration offset, expected result, case number" into a structure, facilitating the management of 20 cases and avoiding code redundancy.
// PHTestCase member description: raw[5]: Stores 5 original pH data points (simulating 5 sampling values from one monitoring point); offset: The calibration offset for the current case (can be positive or negative, covering different calibration scenarios); expected[5]: Pre-calculated expected results after calibration (used for subsequent verification); caseID: Case number (e.g., Case01), used to distinguish different cases during output.

// Implement the core calibration function (original code only described it without definition)
void calibratePH(float* phArr, int len, float offset) {
    float* ptr = phArr; // Pointer points to the first element of the array
    for (int i = 0; i < len; i++) {
        *ptr += offset;   // Dereference pointer to modify the current element value
        ptr++;            // Pointer moves to point to the next element
    }
}

