        for (int j = 0; j < dataLen; j++) cout << currentCase.expected[j] << " ";

        // 4. Verification: Determine if actual calibration results match expectations (allow small floating-point error, use 1e-6 as threshold)
        bool isCorrect = true;
        for (int j = 0; j < dataLen; j++) {
            // Floating-point comparison: Avoid misjudgment due to precision issues (e.g., 6.3000001 vs 6.3)
            if (fabs(rawPH[j] - currentCase.expected[j]) > 1e-6) {
                isCorrect = false;
                break; // As long as one data point doesn't match, directly judge as verification failure
            }
        }

        // 5. Output verification result
        cout << "| Result Verification: " << (isCorrect ? "true" : "false") << "\n";
    }

    // -------------------------- Overall Verification Summary --------------------------
    int passCount = 0;
    for (int i = 0; i < caseCount; i++) {
        PHTestCase& currentCase = testCases[i];
        int dataLen = 5;
        float rawPH[5];
        for (int j = 0; j < dataLen; j++) rawPH[j] = currentCase.raw[j];

        calibratePH(rawPH, dataLen, currentCase.offset);
        bool isPass = true;
        for (int j = 0; j < dataLen; j++) {
            if (fabs(rawPH[j] - currentCase.expected[j]) > 1e-6) {
                isPass = false;
                break;
            }
        }
        if (isPass) passCount++;
    }

    cout << "===================== Overall Verification Summary =====================\n";
    cout << "Total Cases: " << caseCount << " | Verification Passed: " << passCount << " | ";
    cout << "Overall Verification Result: " << (passCount == caseCount ? "true (All Passed)" : "false (Some Cases Failed)") << endl;

    return 0;
}

