    LaneFlow* lanes;     // Pointer to the lane data array
    int laneNum;         // Number of lanes
};

// Supplement core function declaration
int calcTotalFlow(RoadFlow* road);

// Structure design: The meaning of nested pointers: LaneFlow (lane-level data): Stores basic information for a single lane, is the "minimum data unit", has no pointer dependencies, only stores specific values (laneID and carCount). RoadFlow (road section-level data): Stores summary information for a single road section, the core is the LaneFlow* lanes pointer — through this pointer pointing to the array of all lane data for this road section, avoiding directly storing arrays within the structure (reduces memory redundancy, flexibly adapts to road sections with different numbers of lanes).
// Core function calcTotalFlow: Parameter type: Receives a RoadFlow* pointer (instead of pass-by-value), avoids copying the entire RoadFlow structure (especially when lane data volume is large, improves efficiency).
// calcTotalFlow traversal logic: 1. Define a LaneFlow * lanePtr pointer, initially pointing to the first lane of the road section (road->lanes); 2. Loop road->laneNum times (number of lanes determines loop count), each time accessing the current lane's traffic flow via lanePtr->carCount and accumulating; 3. After each loop, lanePtr++ (pointer offset by 1 LaneFlow size, pointing to the next lane), essentially traversing the array via pointer arithmetic.

// Implement core function (remove extra commas)
int calcTotalFlow(RoadFlow* road) {
    if (road == nullptr || road->lanes == nullptr || road->laneNum <= 0) {
        return 0; // Exception handling
    }
    int total = 0;
    LaneFlow* lanePtr = road->lanes;
    for (int i = 0; i < road->laneNum; i++) {
        total += lanePtr->carCount;
        lanePtr++;
    }
    return total;
}

