// Find the maximum value in sensor data: exclude invalid values, return the maximum value among valid data
// Function findMax detailed explanation: This function is the core of sensor data processing, responsible for excluding invalid values (-999) from the specified data and finding the maximum value, solving the vulnerability in the original code where "the initial value might be an invalid value"
// 1. Initialize the maximum value: first traverse the data to find the first valid value (non -999), use it as the initial maximum value maxVal; if all data are invalid, directly return -999 to avoid subsequent logic errors
// 2. Pointer arithmetic traversal: use endPtr = dataPtr + len to define the traversal termination boundary (pointer points to the position next to the end of the array); in the loop, move the pointer via dataPtr++, check each data one by one: only when the data is valid and greater than the current maxVal, update maxVal

int main() {
    // -------------------------- 20 sensor data test cases --------------------------
    // Each case format: {temperature1, temperature2, temperature3, temperature4, temperature5, temperature6, humidity1, humidity2, humidity3, humidity4, humidity5, humidity6, expected maximum temperature, expected maximum humidity}
    // Note: -999 is an invalid value, each case contains 6 temperature data, 6 humidity data, total 12 sensor values
    struct SensorCase {
        float data[12];       // Sensor raw data (first 6 temp + last 6 hum)
        float expMaxTemp;     // Expected maximum temperature
        float expMaxHum;      // Expected maximum humidity
        const char* caseName; // Case name (for easy distinction)
    };

    // 20 specific cases (covering scenarios like valid values, invalid values, boundary values, all valid, containing multiple invalid values, etc.)
    SensorCase cases[] = {
        // Case 1: contains 1 invalid temperature, 1 invalid humidity
        {{25.3, -999, 26.1, 24.8, 27.2, 25.9, 65.2, 62.5, -999, 59.8, 68.3, 64.6}, 27.2, 68.3, "Case 1: single invalid temp + single invalid hum"}
    };

    // Calculate total number of cases
    int caseCount = sizeof(cases) / sizeof(cases[0]);
    cout << "=== 20 Sensor Data Maximum Value Search and Verification ===  ";

    // Traverse each case, perform maximum value search and verification
    for (int i = 0; i < caseCount; i++) {
        SensorCase current = cases[i];
        // 1. Output current case name
        cout << "【" << current.caseName << "】 ";

        // 2. Extract temperature data (first 6 elements), call findMax to get actual maximum temperature
        float* tempData = current.data; // Temperature data pointer (points to the first element of the array)
        float actualMaxTemp = findMax(tempData, 6, -999);
        // Extract humidity data (last 6 elements), pointer offset by 6 points to the start of humidity data
        float* humData = current.data + 6; // Humidity data pointer (points to the 7th element)
        float actualMaxHum = findMax(humData, 6, -999);

        // 3. Output actual results and expected results
        cout << "  Temperature data: ";
        for (int j = 0; j < 6; j++) {
            if (current.data[j] == -999) cout << "invalid ";
            else cout << current.data[j] << " ";
        }
        cout << "   Actual maximum temperature: " << actualMaxTemp << "℃ | Expected maximum temperature: " << current.expMaxTemp << "℃ ";

        cout << "  Humidity data: ";
        for (int j = 6; j < 12; j++) {
            if (current.data[j] == -999) cout << "invalid ";
            else cout << current.data[j] << " ";
        }
        cout << "   Actual maximum humidity: " << actualMaxHum << "% | Expected maximum humidity: " << current.expMaxHum << "% ";

        // 4. Verify if actual results match expected results (considering floating-point precision, allow ±0.0001 error)
        const float eps = 1e-4; // Floating-point comparison precision threshold
        bool tempCheck = (fabs(actualMaxTemp - current.expMaxTemp) < eps);
        bool humCheck = (fabs(actualMaxHum - current.expMaxHum) < eps);
        bool totalCheck = tempCheck && humCheck;

        // 5. Output verification result
        cout << "  Temperature check: " << (tempCheck ? "true" : "false") << " | Humidity check: " << (humCheck ? "true" : "false") << " ";
        cout << "  Case total check: " << (totalCheck ? "true" : "false") << "  ";
    }

    // Count the pass rate of all cases
    int passCount = 0;
    for (int i = 0; i < caseCount; i++) {
        SensorCase current = cases[i];
        float actualMaxTemp = findMax(current.data, 6, -999);
        float actualMaxHum = findMax(current.data + 6, 6, -999);
        bool tempCheck = (fabs(actualMaxTemp - current.expMaxTemp) < 1e-4);
        bool humCheck = (fabs(actualMaxHum - current.expMaxHum) < 1e-4);
        if (tempCheck && humCheck) passCount++;
    }

    cout << "=== Overall Statistical Results ===" << endl;
    cout << "Total cases: " << caseCount << " | Passed cases: " << passCount << endl;
    cout << "Overall verification pass rate: " << (float)passCount / caseCount * 100 << "%" << endl;
    cout << "Overall verification result: " << (passCount == caseCount ? "true" : "false") << endl;

    return 0;
}

