#include <iostream>
#include <cstdlib>
#include <cmath> // For fabs function (calculates absolute value of floating-point numbers)
using namespace std;

// Calculate the daily average vibration value for a single device
// vibPtr: Pointer to the device's daily vibration data, dayCount: Number of monitoring days
// Parameters: float* vibPtr: Pointer to a device's 5-day vibration data (array starting address); int dayCount: Fixed as 5 (number of monitoring days)

int main() {
    int deviceNum = 20;    // Total number of devices: 20
    int dayCount = 5;      // Number of monitoring days per device: 5 days

    // 1. Dynamically allocate a 2D array: store 5-day vibration data for 20 devices
    float** vibData = new float* [deviceNum];
    for (int i = 0; i < deviceNum; i++) {
        vibData[i] = new float[dayCount];
    }

    // 2. Initialize 5-day vibration data for 20 devices (unit: mm/s²)
    vibData[0] = new float[5] {1.2, 1.5, 1.3, 1.4, 1.6};  // Device 1

    // 3. Expected daily average vibration values for 20 devices (manually calculated average of 5-day data)
    float* expectedAvgs = new float[20] {
        1.4,   // Device 1: (1.2+1.5+1.3+1.4+1.6)/5 = 1.4
        };

    // 4. Traverse 20 devices: calculate actual average, output results, verify consistency with expected values
    for (int i = 0; i < deviceNum; i++) {
        float actualAvg = calcDailyVib(vibData[i], dayCount); // Calculate actual average
        // Output device number, actual average
        cout << "Device" << (i + 1) << " - Actual daily average vibration value: " << actualAvg
            << " | Expected daily average vibration value: " << expectedAvgs[i];
        // Verification: Allow floating-point error of 0.01 (avoid misjudgment due to precision issues)
        bool isCorrect = (fabs(actualAvg - expectedAvgs[i]) <= 0.01f);
        // Output verification result
        cout << " | Verification result: " << (isCorrect ? "true" : "false") << " ";
    }

    // 5. Release dynamically allocated memory (avoid memory leaks)
    for (int i = 0; i < deviceNum; i++) {
        delete[] vibData[i]; // Release 5-day data for each device
    }
    delete[] vibData;       // Release device pointer array
    delete[] expectedAvgs;  // Release expected average array

    return 0;
}

