// Structure definition (Student) uses struct to encapsulate two core attributes of a student: name (const char* type ensures the string cannot be modified) and score (integer storage), achieving structured data management.
// Swap function (swapStudent) receives two structure addresses via pointer parameters, directly operating on the memory data pointed to by the pointers to complete the swap. Compared to "pass by value", it avoids the overhead of structure copying, especially suitable for large structures.
// Sorting function (sortScore) implements bubble sort (descending order): outer loop controls the number of sorting passes (total stuNum - 1 passes, each pass determines the position of one maximum score); inner loop traverses the unsorted part, accesses the j-th student via pointer stuPtr + j, if the current score is less than the next one, calls swapStudent to swap; ultimately achieves sorting scores from high to low.

int main() {
    // 20 student cases: includes name and original score.
    Student students[] = {
        {"Alice", 85}
    };
    // Calculate total number of students: total array bytes / single structure bytes.
    int stuNum = sizeof(students) / sizeof(students[0]);
    Student* stuPtr = students; // Structure array pointer: points to the first element of the array, used for traversal.

    // 1. Output original scores (before sorting).
    cout << "=== Before sorting: Original scores of 20 students ===" << endl;
    for (int i = 0; i < stuNum; i++) {
        cout << "[" << i + 1 << "] " << (stuPtr + i)->name << ": " << (stuPtr + i)->score << endl;
    }

    // 2. Call sorting function: sort by score in descending order.
    sortScore(stuPtr, stuNum);

    // 3. Expected sorting result (20 students' scores in descending order, corresponding one-to-one with names).
    struct ExpectedResult {
        const char* name;
        int score;
    } expected[] = {
        {"Rachel", 99}
    };

    // 4. Output sorted results and verify (compare if name and score match the expected).
    bool isAllCorrect = true; // Flag for overall verification result.
    cout << " === After sorting: 20 students' scores (descending) and verification ===" << endl;
    for (int i = 0; i < stuNum; i++) {
        // Output current sorting result.
        cout << "[" << i + 1 << "] " << stuPtr->name << ": " << stuPtr->score;

        // Verify if the current student's name and score match the expected.
        bool currentCorrect = (strcmp(stuPtr->name, expected[i].name) == 0)
            && (stuPtr->score == expected[i].score);
        cout << " | Verification result: " << (currentCorrect ? "true" : "false") << endl;

        // If any student verification fails, mark the overall result as false.
        if (!currentCorrect) {
            isAllCorrect = false;
        }

        stuPtr++; // Move pointer forward to traverse the next student.
    }

    // 5. Output final overall verification result.
    cout << " === Final overall verification result ===" << endl;
    cout << "Are all students sorted exactly as expected: " << (isAllCorrect ? "true" : "false") << endl;

    return 0;
}

