    // -------------------------- Test Case 1: Statistics for Beijing region (full array) --------------------------
    cout << "=== Test Case 1: Statistics for Beijing region (full array) ===" << endl;
    Parcel parcels1[] = {
        {"Beijing", 1.2}, {"Shanghai", 0.8}, {"Beijing", 1.5},
        {"Guangzhou", 2.1}, {"Beijing", 0.9}, {"Shanghai", 1.3},
        {"Beijing", 1.1}, {"Guangzhou", 1.8}, {"Shanghai", 0.7}
    };
    int len1 = sizeof(parcels1) / sizeof(parcels1[0]);
    float exp1 = (1.2 + 1.5 + 0.9 + 1.1) / 4; // Expected: 1.175
    float res1 = calcAvgWeight(parcels1, len1, "Beijing");
    cout << "Beijing region average weight: " << res1 << "kg ";
    cout << "Expected average weight: " << exp1 << "kg ";
    cout << "Verification result: " << (fabs(res1 - exp1) < 0.001 ? "true" : "false") << "  ";

    return 0;
}

