#include <iostream>
#include <cstdlib>
#include <iomanip>  
using namespace std;

// Structure definition BatteryCycle: Stores the "cycle count (cycle)" and "remaining state of charge (soc, unit %)" for a single battery cycle, used to describe the state during the battery cycling process.
// Structure definition TestCase (defined within main function): Stores the test case's "initial state of charge (initial)", "current state of charge (current)", and "expected decay rate (expected)", used for batch validation of code correctness.
// Core function calcDecayRate functionality: Calculates the battery state of charge decay rate, formula: (initial - current) / initial * 100 (converted to percentage for easier understanding); Exception handling: If initial ≤ 0, output an error message and return -1.0f (indicating calculation failure) to avoid a mathematical "division by zero" error.

int main() {
    // Define 20 sets of test cases: each set contains initial state of charge, current state of charge, and expected decay rate (rounded to 2 decimal places).
    struct TestCase {
        float initial;
        float current;
        float expected;
    } testCases[20] = {
        {100.0f, 95.0f, 5.00f}
    };

    // Iterate through the 20 sets of cases, calculate and verify the results.
    for (int i = 0; i < 20; i++) {
        cout << "=== Test Case " << (i + 1) << " ===" << endl;
        float actual = calcDecayRate(testCases[i].initial, testCases[i].current);

        // Output the calculation result (rounded to 2 decimal places, ensuring uniform formatting).
        if (actual == -1.0f) {
            cout << "Calculation result: Initial state of charge is abnormal" << endl;
        }
        else {
            cout << "Initial state of charge: " << testCases[i].initial << "%, Current state of charge: " << testCases[i].current << "%" << endl;
            cout << "Calculated decay rate: " << fixed << setprecision(2) << actual << "%" << endl;
            cout << "Expected decay rate: " << fixed << setprecision(2) << testCases[i].expected << "%" << endl;
        }

        // Determine if the actual result matches the expected result (considering floating-point precision error, allowing a deviation of ±0.01).
        bool isMatch = false;
        if (testCases[i].expected == -1.0f) {
            isMatch = (actual == -1.0f); // Special judgment for error cases.
        }
        else {
            // Floating-point comparison: considered a match if the absolute difference is less than 0.01.
            isMatch = (abs(actual - testCases[i].expected) < 0.01f);
        }

        cout << "Result match: " << (isMatch ? "true" : "false") << endl << endl;
    }

    return 0;
}

