// -------------------------- Universal Verification Function: Check if Actual Normalization Result Matches Expected --------------------------
bool verifyNormResult(const float* actual, const float* expected, size_t count) {
    const float eps = 1e-6;
    for (size_t i = 0; i < count; i++) {
