#include <iostream>
#include <algorithm>
#include <cmath>
using namespace std;

class OutlierDetector {
private:
    double* data;       // Store the original dataset (copy to avoid modifying external data)
    int size;           // Number of elements in the dataset
    bool* isOutlier;    // Mark array: true = outlier, false = normal value (initialized all false)
    double Q1, Q3, IQR; // Quartiles (Q1 = lower quartile, Q3 = upper quartile), Interquartile Range
    double lowerBound;  // Outlier lower bound (Q1 - 1.5*IQR)
    double upperBound;  // Outlier upper bound (Q3 + 1.5*IQR)

public:
    // Constructor: initialize dataset, copy external data to internal array, initialize mark array
    OutlierDetector(double* raw, int s) : size(s) {
        data = new double[size];
        for (int i = 0; i < size; i++) data[i] = raw[i]; // Deep copy external data

        isOutlier = new bool[size](); // Dynamic array initialization: all elements default false
    }

    // Helper function 1: IQR outlier detection core logic (calculate quartiles, bounds, mark outliers)
    void detectByIQR() {
        // 1. Sort the dataset (sorting is prerequisite for calculating quartiles)
        sort(data, data + size);

        // 2. Calculate quartiles Q1 and Q3 (simplified version: take by index, suitable for any size dataset)
        Q1 = data[size / 4];          // Lower quartile: 25th percentile (index = size/4)
        Q3 = data[3 * size / 4];      // Upper quartile: 75th percentile (index = 3*size/4)
        IQR = Q3 - Q1;                // Interquartile range: upper quartile - lower quartile

        // 3. Calculate outlier judgment boundaries
        lowerBound = Q1 - 1.5 * IQR;
        upperBound = Q3 + 1.5 * IQR;

        // 4. Mark outliers (values less than lower bound or greater than upper bound are outliers)
        for (int i = 0; i < size; i++) {
            isOutlier[i] = (data[i] < lowerBound) || (data[i] > upperBound);
        }
    }

    // Helper function 2: Get outlier mark array (for external verification)
    bool* getOutlierMarks() const {
        return isOutlier;
    }

    // Helper function 3: Get calculated bounds (for external verification)
    void getBounds(double& lower, double& upper) const {
        lower = lowerBound;
        upper = upperBound;
    }

    // Helper function 4: Get sorted dataset (for external verification of quartile calculation)
    double* getSortedData() const {
        return data;
    }

    // Destructor: release dynamically allocated memory to avoid memory leaks
    ~OutlierDetector() {
        delete[] data;
        delete[] isOutlier;
    }
};

// Main function: 20 test cases (covering different data scenarios, including result judgment and true/false output)
int main() {
    // ------------------------------ Case 1: No outliers (uniformly distributed data)
    cout << "=== Case 1: No outliers (uniform distribution) ===" << endl;
    double data1[] = { 1,2,3,4,5,6,7,8 };
    int size1 = sizeof(data1) / sizeof(data1[0]);
    OutlierDetector od1(data1, size1);
    od1.detectByIQR();
    bool* marks1 = od1.getOutlierMarks();
    // Expected: All values normal (false)
    bool res1 = true;
    for (int i = 0; i < size1; i++) {
        if (marks1[i]) res1 = false;
    }
    cout << "Outlier marks (0=normal, 1=outlier): ";
    for (int i = 0; i < size1; i++) cout << marks1[i] << " ";
    cout << " Result matches expectation (no outliers): " << (res1 ? "true" : "false") << "  ";

    return 0;
}

