#include <time.h>
#include <iostream>
#include <cassert>
using namespace std;

struct TimePoint 
{
    // Time point structure: stores timestamp and corresponding value
    // Timestamp (in seconds, since 1970-01-01 00:00:00 UTC)
    // Value corresponding to the time point (e.g., temperature, humidity, etc.)
    time_t timestamp;
    double value;
};

class TimeSeriesDataset 
{
private:
    TimePoint* data;  
    int len;          
public:
    TimeSeriesDataset(int l) : len(l) 
    {
        // 1. Constructor: Initialize len time points, with a time interval of 1 hour (3600 seconds), initial value 0.0
        // Boundary handling: avoid negative or zero length
        if (len <= 0)
        {
            len = 0;
            data = nullptr;
            return;
        }
        data = new TimePoint[len];
        time_t now = time(nullptr);
        for (int i = 0; i < len; ++i)
        {
            data[i].timestamp = now - i * 3600;
            data[i].value = 0.0;
        }
    }

    ~TimeSeriesDataset() 
    {
        // 2. Destructor: Release dynamic array memory to avoid memory leaks
        delete[] data;
        data = nullptr;
    }

    int getLength() const 
    {
        // 3. Get data length (provides external access interface for len, hides private member)
        return len;
    }

    time_t getTimestamp(int index) const 
    {
        // 4. Get the timestamp at the specified index (index 0 is the latest time, larger indices indicate older times)
        // Boundary handling: return -1 (invalid timestamp) when index is out of bounds
        if (index < 0 || index >= len)
            return -1;
        return data[index].timestamp;
    }

    double getValue(int index) const 
    {
        // 5. Get the value at the specified index
        // Boundary handling: return NaN (invalid value) when index is out of bounds
        if (index < 0 || index >= len)
            return nan("");
        return data[index].value;
    }

    bool setValue(int index, double newVal) 
    {
        // 6. Modify the value at the specified index (supports data updates)
        // Modification fails and returns false when index is out of bounds
        if (index < 0 || index >= len)
            return false;
        data[index].value = newVal;
        return true;
    }

    bool isTimestampSorted() const 
    {
        // 7. Check if timestamps are sorted from "newest to oldest" (verify construction logic)
        for (int i = 0; i < len - 1; ++i)
        {
            if (data[i].timestamp <= data[i + 1].timestamp)
                return false;
        }
        return true;
    }
};

int main() 
{
    // Case 1: Create 24-hour data, verify if the length is 24
    cout << "=== Case 1: Verify 24-hour data length ===" << endl;
    TimeSeriesDataset ts1(24);
    int actualLen1 = ts1.getLength();
    int expectedLen1 = 24;
    cout << "Actual length: " << actualLen1 << ", Expected length: " << expectedLen1 << endl;
    cout << (actualLen1 == expectedLen1 ? "true" : "false") << endl << endl;

    return 0;
}

