#include <cstdlib>
#include <ctime>   
#include <cstdio>  
#include <iostream> 
using namespace std; 

class RandomIntDataset 
{
private:
    int* data; 
    int size;   
public:
    RandomIntDataset(int s) : size(s) 
    {
        // Constructor: Generate a random integer array of the specified size (range 0-99)
        // If the passed size is less than or equal to 0, create an array of size 1 by default (to avoid illegal memory allocation)
        // Loop to assign a random integer between 0-99 to each array element
        if (size <= 0)
            size = 1;
        data = new int[size];
        for (int i = 0; i < size; ++i)
            data[i] = rand() % 100;
    }

    void print() 
    {
        // Helper function 1: Print the dataset
        for (int i = 0; i < size; ++i)
        {
            cout << data[i];
            if (i != size - 1)
                cout << " ";
        }
        cout << endl;
    }

    int getSize() const 
    {
        // Helper function 2: Get the dataset size (used for main function judgment)
        return size;
    }

    int getElement(int index) const 
    {
        // Helper function 3: Get the element at the specified index in the array (used for main function judgment)
        // If the index is out of bounds, return -1 (as an illegal identifier)
        if (index < 0 || index >= size)
            return -1;
        return data[index];
    }

    bool hasValue(int val) const 
    {
        // Helper function 4: Determine whether the dataset contains the specified value (used for main function judgment)
        for (int i = 0; i < size; ++i)
            if (data[i] == val)
                return true;
        return false;
    }

    int getMax() const 
    {
        // Helper function 5: Get the maximum value in the dataset (used for main function judgment)
        if (size == 0)
            return -1; // Theoretically will not trigger, as the constructor guarantees size>=1
        int maxVal = data[0];
        for (int i = 1; i < size; ++i)
            if (data[i] > maxVal)
                maxVal = data[i];
        return maxVal;
    }

    ~RandomIntDataset() 
    {
        // Destructor: Release dynamically allocated memory (to avoid memory leaks)
        delete[] data;
    }
};

int main() 
{
    srand((unsigned int)time(NULL));

    // Case 1: Create a dataset of size 5, determine if the size is 5
    cout << "=== Case 1 ===" << endl;
    RandomIntDataset ds1(5);
    ds1.print();
    int actualSize1 = ds1.getSize();
    int expectSize1 = 5;
    cout << "Actual size: " << actualSize1 << ", Expected size: " << expectSize1;
    cout << ", Judgment result: " << (actualSize1 == expectSize1 ? "true" : "false") << endl << endl;

    return 0;
}

