#include <iostream>  
using namespace std; 

class IrisDataset 
{
private:
    float* sepalLen; 
    int sampleCount; 
public:
    IrisDataset() : sampleCount(3) 
    {
        // Constructor: Parameterless initialization, creates sepal length data for 3 samples by default
        // Dynamically allocates a float array and initializes it with classic sample values from the Iris dataset
        sepalLen = new float[sampleCount];
        sepalLen[0] = 5.1f;
        sepalLen[1] = 4.9f;
        sepalLen[2] = 4.7f;
    }

    IrisDataset(int count, const float* data) : sampleCount(count) 
    {
        // Overloaded Constructor 1: Supports custom sample count and sepal length data
        // Copies values from the externally provided data array to the internal class array
        sepalLen = new float[sampleCount];
        for (int i = 0; i < sampleCount; ++i)
            sepalLen[i] = data[i];
    }

    IrisDataset(int count) : sampleCount(count) 
    {
        // Overloaded Constructor 2: Supports custom sample count only (array initialized to 0)
        sepalLen = new float[sampleCount]();
    }

    float getMean() 
    {
        // Helper Function 1: Gets the mean of the sepal length feature
        if (sampleCount <= 0)
            return 0.0f;
        float sum = 0.0f;
        for (int i = 0; i < sampleCount; ++i)
            sum += sepalLen[i];
        return sum / sampleCount;
    }

    float getSepalLen(int index) 
    {
        // Helper Function 2: Gets the sepal length at the specified index (for single sample value verification)
        // Index validity check: Prevents out-of-bounds access
        if (index < 0 || index >= sampleCount)
            return -1.0f; // Out-of-bounds identifier
        return sepalLen[index];
    }

    int getSampleCount() 
    {
        // Helper Function 3: Gets the total sample count (for verifying sample quantity)
        return sampleCount;
    }

    ~IrisDataset() 
    {
        // Destructor: Releases the dynamically allocated array memory to avoid memory leaks
        delete[] sepalLen;
    }
};

int main() 
{
    // ------------------- Test Cases 1-5: Verify sample values from default construction -------------------
    cout << "=== Test Case 1: Default Construction - Get sepal length of sample 0 ===" << endl;
    IrisDataset iris1;
    float val1 = iris1.getSepalLen(0);
    cout << "Actual result: " << val1 << ", Expected result: 5.1" << endl;
    cout << "Verification result: " << (val1 == 5.1f ? "true" : "false") << endl << endl;

    return 0;
}

