#include <iostream>
#include <cassert>
using namespace std;

class GrayImageDataset
{
private:
    unsigned char* pixels;
    int width, height;
public:
    GrayImageDataset(int w, int h) : width(w), height(h)
    {
        pixels = new unsigned char[width * height]();
    }

    void setPixel(int x, int y, unsigned char val)
    {
        if (x >= 0 && x < width && y >= 0 && y < height)
        {
            int index = y * width + x;
            pixels[index] = val;
        }
    }

    unsigned char getPixel(int x, int y)
    {
        if (x >= 0 && x < width && y >= 0 && y < height)
        {
            int index = y * width + x;
            return pixels[index];
        }
        return 0;
    }

    ~GrayImageDataset()
    {
        delete[] pixels;
    }
};

int main()
{
    // Example 1: 2x2 image, assign 255 (white) to (0,0), verify if the value is 255
    GrayImageDataset img1(2, 2);
    img1.setPixel(0, 0, 255);
    unsigned char res1 = img1.getPixel(0, 0);
    cout << "Example 1: Pixel value at (0,0) = " << (int)res1;
    bool exp1 = (res1 == 255);
    cout << ", Is the expectation met: " << boolalpha << exp1 << endl;

    return 0;
}

