using namespace std;

class FileDataset 
{
protected:
    string filePath; 
public:
    // Constructor: Initialize the dataset file path
    FileDataset(string path) : filePath(path) {}

    // Pure virtual function: Core interface for reading the dataset (core of polymorphism), subclasses must implement specific logic
    virtual bool readData() = 0;
    // Helper function: Get the dataset file path (provides a unified way to access the path)
    string getFilePath() { return filePath; }

    // Destructor: Virtual destructor, ensures the correct destructor logic is called when subclass objects are destroyed
    virtual ~FileDataset() {}
};

class CsvDataset : public FileDataset 
{
public:
    // Constructor: Call the parent class constructor to initialize the file path
    CsvDataset(string path) : FileDataset(path) {}

