#include <iostream>
#include <vector>
#include <string>
using namespace std;

class TimeSeriesDataset 
{
protected:
    vector<double> values; 
public:
    // Constructor: Initialize data container
    TimeSeriesDataset(vector<double> v) : values(v) {}
    // Pure virtual function: Define interface for output by time format (must be implemented by subclasses)
    virtual void printByTimeFormat(string format) = 0;
    // Member function: Get data length (number of data points)
    int getDataLength() { return values.size(); }
    // Virtual destructor: Ensure correct destructor logic is called when subclass objects are destroyed
    virtual ~TimeSeriesDataset() {}
};

class UnixTimeDataset : public TimeSeriesDataset 
{
public:
    // Constructor: Call parent class constructor to initialize data
    UnixTimeDataset(vector<double> v) : TimeSeriesDataset(v) {}

    void printByTimeFormat(string format) override 
    {
        // Override parent class pure virtual function: Implement output logic for Unix time format
        if (values.empty()) {
            cout << "Data container is empty, no data to output!" << endl;
            return;
        }
        cout << "Unix time format (" << format << ") output data points:" << endl;
        for (int i = 0; i < values.size(); ++i) {
            cout << "Data point " << (i + 1) << ": " << values[i] << " (Unix timestamp)" << endl;
        }
    }
};

int main() 
{
    // Test case 1: Empty data container
    vector<double> data1;
    UnixTimeDataset ds1(data1);
    cout << "Test case 1 - Output result:";
    ds1.printByTimeFormat("timestamp");
    bool case1 = (ds1.getDataLength() == 0);
    cout << "Test case 1 - Does the result match expectation (expected 0 data points): " << (case1 ? "true" : "false") << endl << endl;

    return 0;
}

