class SensorDataset
{
protected:
    vector<float> readings;
    string deviceId;
public:
    // Constructor: Initialize sensor readings and device ID
    SensorDataset(vector<float> r, string id) : readings(r), deviceId(id) {}

    // Pure virtual function: Calibrate data (subclasses must implement specific calibration logic, demonstrating polymorphism)
    virtual void calibrate() = 0;

    // Member function: Get device ID (provides external access interface for device identification)
    string getDeviceId() { return deviceId; }

    // Member function: Get the number of readings (used to verify the number of data points, assisting in judgment logic)
    int getReadingCount() { return readings.size(); }
};

class TemperatureSensorDataset : public SensorDataset
{
public:
    // Constructor: Call the parent class constructor to initialize temperature sensor data
    TemperatureSensorDataset(vector<float> r, string id) : SensorDataset(r, id) {}

    void calibrate() override
    {
        // Override the calibration function: Implement calibration logic for the temperature sensor (print calibration information)
        cout << "Calibrating temperature sensor [" << deviceId << "], total " << readings.size() << " data points" << endl;
        cout << "Temperature calibration complete: Offset correction +0.1°C" << endl; // Simulate calibration logic
    }
};

