#include <iostream>  
#include <string>
using namespace std;

class DistributedDataset 
{
protected:
    int nodeCount; 
public:
    DistributedDataset(int nodes) : nodeCount(nodes) {}
    // Pure virtual function: defines the interface for synchronizing node data, subclasses must implement it.
    virtual bool syncNodes() = 0;
    // Helper function: verifies if the node count is valid (at least 1).
    bool isValidNodeCount() { return nodeCount >= 1; }
    // New interface to get the node count, used for validation in the main function.
    int getNodeCount() { return nodeCount; }
};

class HdfsDataset : public DistributedDataset 
{
public:
    HdfsDataset(int nodes) : DistributedDataset(nodes) {}

    bool syncNodes() override 
    {
        // Override the pure virtual function, implementing the node synchronization logic for the HDFS dataset.
        if (isValidNodeCount())
        {
            cout << "HDFS node synchronization successful, current node count: " << nodeCount << "  "; 
            return true;
        }
        else
        {
            cout << "HDFS node count is invalid (requires at least 1), synchronization failed  "; 
            return false;
        }
    }
};

int main() 
{
    // Test case 1: node count = 1 (valid, expected synchronization success).
    HdfsDataset h1(1);
    bool res1 = h1.syncNodes();
    bool exp1 = true;
    cout << "Case 1 - Actual Result: " << boolalpha << res1 << ", Expected Result: " << exp1
        << ", Match: " << (res1 == exp1 ? "true" : "false") << "  ";

    return 0;
}

