#include <vector>
#include <string>
#include <iostream>
using namespace std;

class SparseDataset 
{
protected:
    vector<pair<int, double>> sparseData; 
public:
    SparseDataset(vector<pair<int, double>> data) : sparseData(data) {}
    // Virtual function: compress data (pure virtual function, forces subclass implementation)
    virtual void compress(string method) = 0;
    // Helper function: calculate the number of non-zero elements (core feature of sparse data)
    int getNonZeroCount() { return sparseData.size(); }
    // New: get sparse data (for test verification)
    vector<pair<int, double>> getSparseData() { return sparseData; }
};

class Lz4SparseDataset : public SparseDataset 
{
public:
    Lz4SparseDataset(vector<pair<int, double>> data) : SparseDataset(data) {}

    void compress(string method) override 
    {
        // Override the compress function: implement the compression logic of the LZ4 algorithm (simulated output here)
        cout << "Using LZ4 algorithm to compress in [" << method << "] mode, number of non-zero elements: " << getNonZeroCount() << endl;
    }
};

int main() 
{
    // Test case 1: empty sparse data (no non-zero elements)
    vector<pair<int, double>> data1;
    Lz4SparseDataset ds1(data1);
    int exp1 = 0; // Expected number of non-zero elements
    int res1 = ds1.getNonZeroCount();
    cout << "Case 1: empty data, non-zero element count=" << res1;
    cout << ", does the result match expectation: " << (res1 == exp1 ? "true" : "false") << endl;
    ds1.compress("Fast");

    return 0;
}

