class StreamDataset 
{
protected:
    string streamUrl; 
public:
    StreamDataset(string url) : streamUrl(url) {}
    // Virtual function: Receive stream data (pure virtual function, making the base class abstract)
    virtual void receiveStream(bool realTime) = 0;
    // Helper function: Check if the stream URL is valid (non-empty is valid)
    bool isStreamUrlValid() { return !streamUrl.empty(); }
    // Helper function: Get the stream URL (used for result judgment in main function)
    string getStreamUrl() { return streamUrl; }
};

class KafkaStreamDataset : public StreamDataset 
{
public:
    KafkaStreamDataset(string url) : StreamDataset(url) {}

    void receiveStream(bool realTime) override 
    {
        // Override base class virtual function: Implement Kafka stream data receiving logic
        if (isStreamUrlValid())
        {
            cout << "Receiving data from Kafka stream [" << streamUrl << "], Mode: " << (realTime ? "Real-time" : "Batch") << endl;
        }
        else
        {
            cout << "Kafka stream URL is invalid, cannot receive data" << endl;
        }
    }
};

