#include <iostream>
#include <vector>
#include <cmath> 
using namespace std;

class DataPreprocessor 
{
protected:
    vector<vector<double>> data;  
    const double EPS = 1e-6;      
public:
    // Constructor 1: Initialize data (Core constructor)
    DataPreprocessor(vector<vector<double>> d) : data(d) {}

    // Constructor 2: Default constructor (Empty data)
    DataPreprocessor() : data() {}

    // Pure virtual function: Data preprocessing (Must be overridden by subclasses to implement specific logic)
    virtual void preprocess() = 0;

    void printData() const 
    {
        // Helper function 1: Output processed data
        for (size_t i = 0; i < data.size(); ++i)
        {
            for (size_t j = 0; j < data[i].size(); ++j)
            {
                cout << data[i][j];
                if (j != data[i].size() - 1) cout << " ";
            }
            cout << endl;
        }
        // Avoid trailing spaces
    }

    vector<vector<double>> getData() const 
    {
        // Helper function 2: Get processed data (For external result verification)
        return data;
    }

    bool isEqual(const vector<vector<double>>& expected) const 
    {
        // Helper function 3: Verify if current data matches expected data (Handles floating-point precision)
        // 1. Check if the number of samples is consistent
        if (data.size() != expected.size()) return false;
        // 2. Check if the number of features per sample is consistent
        for (size_t i = 0; i < data.size(); ++i)
        {
            if (data[i].size() != expected[i].size()) return false;
        }
        // 3. Check each element value for consistency (Tolerates minor errors)
        for (size_t i = 0; i < data.size(); ++i)
        {
            for (size_t j = 0; j < data[i].size(); ++j)
            {
                if (fabs(data[i][j] - expected[i][j]) > EPS) return false;
            }
        }
        return true;
    }

    bool isEmpty() const 
    {
        // Helper function 4: Check if data is empty
        return data.empty();
    }
};

class Normalizer : public DataPreprocessor 
{
public:
    // Constructor: Reuse base class constructor
    Normalizer(vector<vector<double>> d) : DataPreprocessor(d) {}

    void preprocess() override 
    {
        // Override virtual function: Implement normalization logic (Calculate min/max per feature column)
        if (data.empty() || data[0].empty()) return;
        size_t featureNum = data[0].size();
        // Calculate min and max for each feature column
        for (size_t j = 0; j < featureNum; ++j)
        {
            // Step 1: Find min and max for this column
            double minVal = data[0][j];
            double maxVal = data[0][j];
            for (size_t i = 1; i < data.size(); ++i)
            {
                if (data[i][j] < minVal) minVal = data[i][j];
                if (data[i][j] > maxVal) maxVal = data[i][j];
            }
            // Avoid division by zero (If all values in the column are the same, set normalized values to 0)
            if (fabs(maxVal - minVal) < EPS)
            {
                for (size_t i = 0; i < data.size(); ++i)
                {
                    data[i][j] = 0.0;
                }
            }
            else
            {
                // Step 2: Normalize (x' = (x - min)/(max - min))
                for (size_t i = 0; i < data.size(); ++i)
                {
                    data[i][j] = (data[i][j] - minVal) / (maxVal - minVal);
                }
            }
        }
    }
};

// Subclass 2: Data Standardization (Z-Score Standardization, mean=0, variance=1)
class Standardizer : public DataPreprocessor 
{
public:
    // Constructor: Reuse base class constructor
    Standardizer(vector<vector<double>> d) : DataPreprocessor(d) {}

    void preprocess() override 
    {
        // Override virtual function: Implement standardization logic (Calculate mean and standard deviation per feature column)
        if (data.empty() || data[0].empty()) return;
        size_t featureNum = data[0].size();
        // Calculate mean and standard deviation for each feature column
        for (size_t j = 0; j < featureNum; ++j)
        {
            // Step 1: Calculate the mean for this column
            double mean = 0.0;
            for (size_t i = 0; i < data.size(); ++i)
            {
                mean += data[i][j];
            }
            mean /= data.size();
            // Step 2: Calculate the standard deviation for this column
            double std = 0.0;
            for (size_t i = 0; i < data.size(); ++i)
            {
                std += pow(data[i][j] - mean, 2);
            }
            std = sqrt(std / data.size());
            // Avoid division by zero (If all values in the column are the same, set standardized values to 0)
            if (fabs(std) < EPS)
            {
                for (size_t i = 0; i < data.size(); ++i)
                {
                    data[i][j] = 0.0;
                }
            }
            else
            {
                // Step 3: Standardize (x' = (x - mean)/std)
                for (size_t i = 0; i < data.size(); ++i)
                {
                    data[i][j] = (data[i][j] - mean) / std;
                }
            }
        }
    }
};

