#include <iostream>
#include <vector>
#include <string>
#include <sstream>  
using namespace std;

class TextTokenizer 
{
protected:
    vector<string> texts; 
public:
    // Constructor 1: Initialize raw text
    TextTokenizer(vector<string> t) : texts(t) {}

    // Constructor 2: Default constructor (empty text)
    TextTokenizer() : texts() {}

    // Pure virtual function: Core tokenization logic (subclasses must override to implement different tokenization rules)
    virtual vector<vector<string>> tokenize() const = 0;

    void printTokens(const vector<vector<string>>& tokens) const 
    {
        // Helper function 1: Output tokenization result details
        for (size_t i = 0; i < tokens.size(); ++i)
        {
            cout << "Text " << i + 1 << " tokens: "; 
            for (size_t j = 0; j < tokens[i].size(); ++j)
            {
                cout << "[" << tokens[i][j] << "]";
                if (j != tokens[i].size() - 1) cout << " ";
            }
            cout << endl;
        }
    }

    int getTotalTokenCount(const vector<vector<string>>& tokens) const 
    {
        // Helper function 2: Count total number of tokens
        int count = 0;
        for (const auto& tokenList : tokens)
        {
            count += tokenList.size();
        }
        return count;
    }

    bool isTokenEqual(const vector<vector<string>>& tokens, const vector<vector<string>>& expected) const 
    {
        // Helper function 3: Verify if tokenization result matches expected result
        // 1. First check if the number of texts matches
        if (tokens.size() != expected.size()) return false;
        // 2. Then check if the token list for each text matches
        for (size_t i = 0; i < tokens.size(); ++i)
        {
            if (tokens[i].size() != expected[i].size()) return false;
            for (size_t j = 0; j < tokens[i].size(); ++j)
            {
                if (tokens[i][j] != expected[i][j]) return false;
            }
        }
        return true;
    }
};

class SpaceTokenizer : public TextTokenizer 
{
public:
    // Constructor: Call base class constructor to initialize text
    SpaceTokenizer(vector<string> t) : TextTokenizer(t) {}

    vector<vector<string>> tokenize() const override 
    {
        // Override virtual function: Implement space tokenization logic (actual string splitting, not simulation)
        vector<vector<string>> result;
        for (const string& text : texts)
        {
            vector<string> tokens;
            istringstream iss(text);
            string token;
            while (iss >> token)
            {
                tokens.push_back(token);
            }
            result.push_back(tokens);
        }
        return result;
    }
};

class CharTokenizer : public TextTokenizer 
{
public:
    // Constructor: Call base class constructor to initialize text
    CharTokenizer(vector<string> t) : TextTokenizer(t) {}

    vector<vector<string>> tokenize() const override 
    {
        // Override virtual function: Implement character-level tokenization logic (iterate through each character)
        vector<vector<string>> result;
        for (const string& text : texts)
        {
            vector<string> tokens;
            for (char c : text)
            {
                // Iterate through each character of the string, convert to string and store in list
                tokens.push_back(string(1, c));
            }
            result.push_back(tokens);
        }
        return result;
    }
};

// Subclass 3: Underscore tokenizer (split by underscore, supplementary scenario: e.g., variable name tokenization)
class UnderscoreTokenizer : public TextTokenizer 
{
public:
    UnderscoreTokenizer(vector<string> t) : TextTokenizer(t) {}

    vector<vector<string>> tokenize() const override 
    {
        vector<vector<string>> result;
        for (const string& text : texts)
        {
            vector<string> tokens;
            size_t start = 0;
            size_t pos = text.find('_');
            while (pos != string::npos)
            {
                if (pos > start)
                {
                    tokens.push_back(text.substr(start, pos - start));
                }
                start = pos + 1;
                pos = text.find('_', start);
            }
            // Add the last unsplit token
            if (start < text.size())
            {
                tokens.push_back(text.substr(start));
            }
            result.push_back(tokens);
        }
        return result;
    }
};

