#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <cmath>
using namespace std;

// Base class: Universal Data Storage (Defines a unified interface for data storage, supports multi-storage medium extension)
// Core functionality: Manages data unique identifier, provides storage interface, supports result verification
class DataStorage
{
protected:
    string dataId;
    const double EPS = 1e-6;

    // Helper function (protected): Simulates storage operation result recording (for verification)
    virtual string getStoreResultRecord() const = 0;

public:
    DataStorage(string id) : dataId(id)
    {
        // Constructor 1: Initializes data ID (with validity check to avoid empty ID)
        if (id.empty())
        {
            throw invalid_argument("Data ID cannot be empty");
        }
    }

    // Constructor 2: Default constructor (empty ID, for special scenarios)
    DataStorage() : dataId("") {}

    // Pure virtual function: Core logic for data storage (Subclasses must override to implement storage for specific medium)
    virtual void store() const = 0;

    string getDataId() const
    {
        // Helper function 1: Gets data ID (for external verification and logging)
        return dataId;
    }

    bool isStoreResultValid(const string& expectedRecord) const
    {
        // Helper function 2: Verifies if storage result matches expectation (compares storage records)
        // Ignores whitespace differences, compares only core content
        string actual = getStoreResultRecord();
        string exp = expectedRecord;
        // Remove all whitespace
        actual.erase(remove_if(actual.begin(), actual.end(), ::isspace), actual.end());
        exp.erase(remove_if(exp.begin(), exp.end(), ::isspace), exp.end());
        return actual == exp;
    }

    void printStoreLog(const string& mediumType, const string& target) const
    {
        // Helper function 3: Outputs storage operation log (unified format, easy to view)
        cout << "Stored data [ID=" << dataId << "] to " << mediumType << " target: " << target << endl;
    }
};

// Derived class 1: File Storage (Inherits universal storage, implements local file storage)
class FileStorage : public DataStorage
{
private:
    string filePath;
    mutable string storeLog;

    string getStoreResultRecord() const override
    {
        // Override: Gets file storage result record (for verification)
        return "FileStore:ID=" + dataId + ",Path=" + filePath;
    }

public:
    FileStorage(string id, string path) : DataStorage(id), filePath(path)
    {
        // Constructor: Initializes data ID + file path (calls base class constructor, ensures ID validity)
        if (path.empty())
        {
            throw invalid_argument("File path cannot be empty");
        }
    }

    void store() const override
    {
         // Override: File storage logic (simulates file write operation, logs)
        storeLog = "File written to " + filePath + " (ID: " + dataId + ")";
        printStoreLog("File", filePath);
    }

    string getFilePath() const
    {
        // Helper function: Gets file path (for external verification)
        return filePath;
    }
};

// Derived class 2: Database Storage (Inherits universal storage, implements relational database storage)
class DBStorage : public DataStorage
{
private:
    string dbConn;
    string tableName;
    mutable string storeLog;

    string getStoreResultRecord() const override
    {
        // Override: Gets database storage result record (for verification)
        return "DBStore:ID=" + dataId + ",Conn=" + dbConn + ",Table=" + tableName;
    }

public:
    DBStorage(string id, string conn, string table)
        : DataStorage(id), dbConn(conn), tableName(table)
    {
        // Constructor: Initializes data ID + connection string + table name (calls base class constructor, ensures ID validity)
        if (conn.empty() || table.empty())
        {
            throw invalid_argument("DB connection or table name cannot be empty");
        }
    }

    void store() const override
    {
        // Override: Database storage logic (simulates SQL insert operation, logs)
        storeLog = "SQL inserted into " + tableName + " via " + dbConn + " (ID: " + dataId + ")";
        printStoreLog("Database", dbConn + "::" + tableName);
    }

    string getDBInfo() const
    {
        // Helper function: Gets database connection information (for external verification)
        return dbConn + "::" + tableName;
    }
};

// Derived class 3: Cloud Storage (New derived class, implements cloud service storage, extends storage medium)
class CloudStorage : public DataStorage
{
private:
    string bucketName;
    string cloudRegion;
    mutable string storeLog;

    string getStoreResultRecord() const override
    {
        // Override: Gets cloud storage result record (for verification)
        return "CloudStore:ID=" + dataId + ",Bucket=" + bucketName + ",Region=" + cloudRegion;
    }

public:
    CloudStorage(string id, string bucket, string region)
        : DataStorage(id), bucketName(bucket), cloudRegion(region)
    {
        // Constructor: Initializes data ID + bucket name + region (calls base class constructor)
        if (bucket.empty() || region.empty())
        {
            throw invalid_argument("Cloud bucket or region cannot be empty");
        }
    }

    void store() const override
    {
        // Override: Cloud storage logic (simulates cloud upload operation, logs)
        storeLog = "Object uploaded to " + bucketName + " (" + cloudRegion + ") (ID: " + dataId + ")";
        printStoreLog("Cloud", cloudRegion + "/" + bucketName);
    }

    string getCloudInfo() const
    {
        // Helper function: Gets cloud storage information (for external verification)
        return cloudRegion + "/" + bucketName;
    }
};

