#include <iostream>
#include <string>
#include <vector>
#include <utility>
using namespace std;

class Feature
{
protected:
    string featName;
    int featDim;
public:
    // Constructor: Initialize feature name and dimension
    Feature(string name, int dim) : featName(name), featDim(dim) {}

    // Destructor: Declared virtual for polymorphic destruction, ensuring derived class objects are correctly released
    virtual ~Feature() = default;

    string getFeatInfo() const
    {
        // Helper function: Get basic feature information
        return "Feature(name=" + featName + ", dim=" + to_string(featDim) + ")";
    }

    // Virtual function: Feature standardization (to be overridden by subclasses)
    virtual void standardize() const = 0;

    // New: Get expected standardization result (for subsequent judgment)
    virtual string getExpectedStdResult() const = 0;
};

// Derived class 1: Numeric Feature (inherits from generic Feature, adds numeric range attribute)
class NumericFeature : public Feature
{
private:
    pair<double, double> valueRange;
    mutable string actualStdResult; // Store actual standardization result
public:
    // Constructor: Initialize feature name, dimension, and numeric range
    NumericFeature(string name, int dim, double min, double max)
        : Feature(name, dim), valueRange({min, max}) {}

    void standardize() const override
    {
        // Override standardization: Numeric feature standardization (scale to [0,1])
        actualStdResult = "NumericFeature '" + featName + "' standardized to [0,1] (range: [" +
                        to_string(valueRange.first) + ", " + to_string(valueRange.second) + "])";
        cout << actualStdResult;
    }

    string getExpectedStdResult() const override
    {
        // Override: Get expected standardization result for numeric feature
        return "NumericFeature '" + featName + "' standardized to [0,1] (range: [" +
               to_string(valueRange.first) + ", " + to_string(valueRange.second) + "])";
    }

    string getActualStdResult() const
    {
        // New: Get actual standardization output string (for comparison)
        return actualStdResult;
    }
};

// Derived class 2: Text Feature (inherits from generic Feature, adds vocabulary size attribute)
class TextFeature : public Feature
{
private:
    int vocabSize;
    mutable string actualStdResult; // Store actual standardization result
