#include <iostream>
#include <vector>
#include <string>
#include <cctype>
using namespace std;

class DataValidator
 {
protected:
 string dataType;
public:
 // Constructor: Initialize data type
 DataValidator (string type) : dataType (type) {}

 // Virtual function: Perform validation (to be overridden by subclasses)
 virtual bool validate (const string& data) const = 0;

 void printResult (const string& data) const
 {
 // Helper function: Output validation result
 bool valid = validate (data);
 cout << "Validate [" << dataType << "] data: '" << data << "' →" << (valid ? "Yes" : "No");
 }

 // Destructor: Ensure proper cleanup of subclass objects
 virtual ~DataValidator () = default;
};

// Derived class 1: Format Validator (inherits from generic validator, validates string formats like email, phone number)
class FormatValidator : public DataValidator
 {
private:
 string formatRule;
public:
 // Constructor: Initialize data type + format rule
 FormatValidator (string type, string rule)
 : DataValidator (type), formatRule (rule) {}

 bool validate (const string& data) const override
 {
 // Override validation: Supports email, phone number (simplified logic)
 if (formatRule == "email")
 {
 // Simplified email validation: Contains @ and ., @ not at start/end, . after @
 size_t atPos = data.find ('@');
 size_t dotPos = data.find ('.', atPos + 1);
 return !data.empty () && atPos != string::npos && atPos != 0 && atPos != data.size ()-1 && dotPos != string::npos && dotPos != data.size ()-1;
 }
 else if (formatRule == "phone")
 {
 // Simplified phone number validation: 11 digits, starts with 1
 if (data.size () != 11) return false;
 if (data [0] != '1') return false;
 for (char c : data)
 {
 if (!isdigit (c)) return false;
 }
 return true;
 }
 return false;
 }
};

// Derived class 2: Range Validator (inherits from generic validator, validates numerical range)
class RangeValidator : public DataValidator
 {
private:
 int minVal, maxVal;
public:
 // Constructor: Initialize data type + numerical range
 RangeValidator (string type, int min, int max)
 : DataValidator (type), minVal (min), maxVal (max) {}

 bool validate (const string& data) const override
 {
 // Override validation: Verify if the number is within the range (handles non-numeric input)
 // First check if it's a pure number (supports negative sign)
 if (data.empty ()) return false;
 size_t i = 0;
 if (data [0] == '-')
 {
 if (data.size () == 1) return false; // Lone minus sign is invalid
 i = 1;
 }
 for (; i < data.size (); ++i)
 {
 if (!isdigit (data [i])) return false;
 }
 // Convert to integer and check range
 int num = stoi (data);
 return num >= minVal && num <= maxVal;
 }
};

int main ()
 {
 // 1. Email format validation: Valid (expected Yes)
 DataValidator* v1 = new FormatValidator ("string", "email");
 bool res1 = v1->validate ("test@example.com");
 v1->printResult ("test@example.com");
 cout << "Result matches expected (Yes):" << (res1 == true ? "true" : "false") << endl << endl;
 delete v1;

 return 0;
}

