#include <iostream>
#include <string>
using namespace std;

class ImageData 
{
protected:
    int width, height; 
    string imgPath;    
public:
    // Constructor: Initialize width, height, path
    ImageData(int w, int h, string path)
        : width(w), height(h), imgPath(path) {}

    string getSize() const 
    {
        // Helper function: Get image dimensions
        return to_string(width) + "x" + to_string(height);
    }

    // Virtual function: Image loading (to be overridden by subclasses)
    virtual void loadImage() const = 0;

    string getPath() const 
    {
        // New: Get image path (for test judgment)
        return imgPath;
    }

    virtual int getGrayLevel() const 
    {
        // New: Get gray level (for grayscale images, returns -1 for color images, for test judgment)
        return -1;
    }

    virtual int getChannels() const 
    {
        // New: Get number of channels (for color images, returns -1 for grayscale images, for test judgment)
        return -1;
    }

    // Destructor: Prevent memory leaks
    virtual ~ImageData() = default;
};

// Derived class 1: Grayscale image (inherits from generic image, adds gray level attribute)
class GrayImage : public ImageData 
{
private:
    int grayLevel; 
public:
    // Constructor: Initialize width, height, path, gray level
    GrayImage(int w, int h, string path, int level)
        : ImageData(w, h, path), grayLevel(level) {}

    void loadImage() const override 
    {
        // Override loading: Grayscale image loading
        cout << "Loading grayscale image from " << imgPath << " (" << getSize() << "), " << grayLevel << " levels" << endl;
    }

    int getGrayLevel() const override 
    {
        // Override: Return gray level
        return grayLevel;
    }
};

// Derived class 2: Color image (inherits from generic image, adds channels attribute)
class ColorImage : public ImageData 
{
private:
    int channels; 
public:
    // Constructor: Initialize width, height, path, number of channels
    ColorImage(int w, int h, string path, int ch)
        : ImageData(w, h, path), channels(ch) {}

    void loadImage() const override 
    {
        // Override loading: Color image loading
        cout << "Loading color image from " << imgPath << " (" << getSize() << "), " << channels << " channels" << endl;
    }

    int getChannels() const override 
    {
        // Override: Return number of channels
        return channels;
    }
};

